@router.get('/providers')
async def list_providers():
    """列出所有支持的模型提供商。"""
    result = []
    for name, provider in PROVIDERS.items():
        result.append({
            'name': provider['name'],
            'display_name': provider['display_name'],
            'description': provider['description'],
            'icon': provider['icon'],
            'default_api_base': provider['default_api_base'],
            'help_url': provider.get('help_url'),
            'model_count': len(provider['models']),
        })
    return result


@router.get('/providers/{name}/models')
async def list_provider_models(name: str):
    """列出指定提供商的模型列表。"""
    provider = PROVIDERS.get(name)
    if not provider:
        return {'error': f'不支持的提供商: {name}'}
    return provider['models']


@router.get('/config')
async def get_llm_config():
    """获取当前 LLM 配置状态。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    # 从 SQLite 读取配置
    db_config = app.db.get_all_llm_config()

    provider = db_config.get('provider', '')
    api_key = db_config.get('api_key', '')
    api_base = db_config.get('api_base', '')
    model_name = db_config.get('model_name', '') or app.config.model_name
    fast_model_name = db_config.get('fast_model_name', '') or getattr(app.config, 'fast_model_name', '')
    configured_at = db_config.get('configured_at', '')

    # 获取提供商信息
    provider_info = None
    if provider and provider in PROVIDERS:
        p = PROVIDERS[provider]
        provider_info = {
            'name': p['name'],
            'display_name': p['display_name'],
            'icon': p['icon'],
        }

    return {
        'configured': bool(api_key),
        'provider': provider,
        'provider_info': provider_info,
        'api_base': api_base,
        'api_key_masked': _mask_key(api_key),
        'model_name': model_name,
        'fast_model_name': fast_model_name,
        'llm_configured': bool(api_key and model_name),
        'configured_at': configured_at,
    }


@router.put('/credentials')
async def put_credentials(req: CredentialsRequest):
    """配置提供商凭据（API Key）。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    provider = req.provider.strip()
    api_key = req.api_key.strip()

    if not provider:
        return {'error': 'provider 不能为空'}
    if not api_key:
        return {'error': 'api_key 不能为空'}
    if provider not in PROVIDERS:
        return {'error': f'不支持的提供商: {provider}'}

    # 确定 api_base
    api_base = (req.api_base or '').strip() or PROVIDERS[provider]['default_api_base']

    # 写入 SQLite
    db = app.db
    db.set_llm_config('provider', provider)
    db.set_llm_config('api_key', api_key)
    db.set_llm_config('api_base', api_base)
    db.set_llm_config('configured_at', datetime.now().isoformat())

    # 热加载到内存 config
    app.config.model_server = api_base
    app.config.llm_api_key = api_key

    logger.info('LLM 凭据已配置: provider=%s, api_base=%s', provider, api_base)

    return {
        'status': 'ok',
        'provider': provider,
        'api_base': api_base,
    }


@router.put('/models')
async def put_models(req: ModelsRequest):
    """设置主模型和快速模型。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    model_name = req.model_name.strip()
    fast_model_name = (req.fast_model_name or '').strip()

    if not model_name:
        return {'error': 'model_name 不能为空'}

    # 写入 SQLite
    db = app.db
    db.set_llm_config('model_name', model_name)
    if fast_model_name:
        db.set_llm_config('fast_model_name', fast_model_name)

    # 热加载到内存 config
    app.config.model_name = model_name
    if fast_model_name:
        app.config.fast_model_name = fast_model_name

    logger.info('LLM 模型已设置: model=%s, fast_model=%s', model_name, fast_model_name)

    return {
        'status': 'ok',
        'model_name': model_name,
        'fast_model_name': fast_model_name or getattr(app.config, 'fast_model_name', ''),
    }


@router.delete('/credentials')
async def clear_llm_credentials():
    """清除 LLM 配置。"""
    from agent_runtime.server.app import get_agent_app
    app = get_agent_app()
    if not app:
        return {'error': 'Agent 未初始化'}

    # 清除 SQLite
    app.db.clear_llm_config()

    # 清除内存
    app.config.model_server = ''
    app.config.llm_api_key = ''

    logger.info('LLM 配置已清除')
    return {'status': 'cleared'}


# ─────────────────────────────────────────────
# 辅助函数
# ─────────────────────────────────────────────

def _mask_key(key: str) -> str:
    """脱敏显示密钥。"""
    if not key:
        return ''
    if len(key) <= 16:
        return '****'
    return key[:8] + '****' + key[-4:]
